import{_ as t,o,c as d,ak as a}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse(`{"title":"Reporter options","description":"Every option of the Piwi Playwright reporter, with its type, default and environment variable, generated from the reporter's options type.","frontmatter":{"title":"Reporter options","description":"Every option of the Piwi Playwright reporter, with its type, default and environment variable, generated from the reporter's options type.","lang":"en-US","editLink":false,"head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/reporter-options.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/reporter-options.html"}],["meta",{"property":"og:title","content":"Reporter options | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Every option of the Piwi Playwright reporter, with its type, default and environment variable, generated from the reporter's options type."}]]},"headers":[],"relativePath":"reference/reporter-options.md","filePath":"reference/reporter-options.md","lastUpdated":null}`),r={name:"reference/reporter-options.md"};function c(s,e,n,i,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="reporter-options" tabindex="-1">Reporter options <a class="header-anchor" href="#reporter-options" aria-label="Permalink to &quot;Reporter options&quot;">​</a></h1><p>These options go in the reporter&#39;s options object in <code>playwright.config.ts</code>, or in <code>wrapConfig</code>&#39;s second argument (see <a href="/guide/reporter.html#configuration-options">Reporter</a>). Most of them can also be set with the environment variable shown in their row. The variable only fills in an option you left unset, so an explicit option always wins, with one exception: on a plain reporter entry, <code>PIWI_VERBOSE</code> overrides even an explicit <code>verbose</code> option (under <code>wrapConfig</code> the option wins).</p><h2 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option and variable</th><th>Type and default</th><th>Description</th></tr></thead><tbody><tr><td><code id="enabled">enabled</code></td><td><code>boolean</code><br><code>true</code> when <code>serverUrl</code> is set</td><td>Explicitly enable or disable the reporter. Defaults to <code>true</code> when <code>serverUrl</code> is set. Set to <code>false</code> to disable even if <code>serverUrl</code> is provided.</td></tr><tr><td><code id="serverurl">serverUrl</code><br><code>PIWI_DASHBOARD_URL</code></td><td><code>string</code><br>no default</td><td>URL of the Piwi Dashboard server</td></tr><tr><td><code id="projectname">projectName</code><br><code>PIWI_PROJECT_NAME</code></td><td><code>string</code><br><code>&#39;default-project&#39;</code></td><td>Name of the project to report results under. Defaults to <code>&#39;default-project&#39;</code>.</td></tr><tr><td><code id="projectdescription">projectDescription</code></td><td><code>string</code><br>no default</td><td>Optional description of the project</td></tr><tr><td><code id="submittimeout">submitTimeout</code><br><code>PIWI_SUBMIT_TIMEOUT</code></td><td><code>number</code><br><code>900000</code> (15 minutes)</td><td>Time budget (ms) for the reporter&#39;s end-of-run work: delivering the last live events, uploading the remaining traces and attachments, and submitting the run. When it runs out, the reporter stops waiting for the dashboard and saves the run&#39;s results locally; the next run for the project uploads them, without traces or attachments. Defaults to <code>900000</code> (15 minutes). Set to <code>0</code> for no limit. Can also be set with <code>PIWI_SUBMIT_TIMEOUT</code>.</td></tr></tbody></table><h2 id="what-gets-uploaded" tabindex="-1">What gets uploaded <a class="header-anchor" href="#what-gets-uploaded" aria-label="Permalink to &quot;What gets uploaded&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option and variable</th><th>Type and default</th><th>Description</th></tr></thead><tbody><tr><td><code id="uploadtraces">uploadTraces</code><br><code>PIWI_UPLOAD_TRACES</code></td><td><code>boolean</code><br><code>true</code></td><td>Upload trace files to the dashboard. Defaults to <code>true</code>.</td></tr><tr><td><code id="uploadreport">uploadReport</code><br><code>PIWI_UPLOAD_REPORT</code></td><td><code>boolean</code><br><code>true</code></td><td>Upload the Playwright HTML report. Defaults to <code>true</code>.</td></tr><tr><td><code id="livefileuploads">liveFileUploads</code><br><code>PIWI_LIVE_FILE_UPLOADS</code></td><td><code>boolean</code><br><code>true</code></td><td>Upload each test&#39;s trace and attachments as soon as the test finishes (streaming mode only). Defaults to <code>true</code>.</td></tr></tbody></table><h2 id="what-gets-captured" tabindex="-1">What gets captured <a class="header-anchor" href="#what-gets-captured" aria-label="Permalink to &quot;What gets captured&quot;">​</a></h2><p>Note the dependency: <code>collectPerformanceMetrics</code> is a master switch for the three <code>capture*</code> toggles below it. Setting it to <code>false</code> forces <code>captureLocators</code>, <code>capturePageState</code> and <code>captureServerTraces</code> off too, because the reporter discards their data in that case — it is the one option here that silently disables others. <code>collectScmInfo</code> and <code>collectCiInfo</code> are independent of it.</p><table tabindex="0"><thead><tr><th>Option and variable</th><th>Type and default</th><th>Description</th></tr></thead><tbody><tr><td><code id="collectscminfo">collectScmInfo</code></td><td><code>boolean</code><br><code>true</code></td><td>Auto-collect git commit, branch, author. Defaults to <code>true</code>.</td></tr><tr><td><code id="collectciinfo">collectCiInfo</code></td><td><code>boolean</code><br><code>true</code></td><td>Auto-collect CI environment info. Defaults to <code>true</code>.</td></tr><tr><td><code id="collectperformancemetrics">collectPerformanceMetrics</code></td><td><code>boolean</code><br><code>true</code></td><td>Collect step timings, network requests and web vitals. Defaults to <code>true</code>.</td></tr><tr><td><code id="capturelocators">captureLocators</code><br><code>PIWI_CAPTURE_LOCATORS</code></td><td><code>boolean</code><br><code>true</code></td><td>Capture per-action locator snapshots that power failure-time healing suggestions. Adds a small per-action cost (one DOM read, sometimes an ARIA snapshot) in the test worker. Defaults to <code>true</code>; automatically disabled when <code>collectPerformanceMetrics</code> is <code>false</code> (the reporter discards the data in that case anyway). Can also be forced off with <code>PIWI_CAPTURE_LOCATORS=false</code>.</td></tr><tr><td><code id="capturepagestate">capturePageState</code><br><code>PIWI_CAPTURE_PAGE_STATE</code></td><td><code>boolean</code><br><code>true</code></td><td>Capture the page&#39;s state at test end (URL, history state, localStorage/ sessionStorage key names + value lengths, cookie names + flags). Values of storage entries and cookies are never captured. Defaults to <code>true</code>; automatically disabled when <code>collectPerformanceMetrics</code> is <code>false</code>. Can also be forced off with <code>PIWI_CAPTURE_PAGE_STATE=false</code>.</td></tr><tr><td><code id="capturepageinventory">capturePageInventory</code><br><code>PIWI_CAPTURE_PAGE_INVENTORY</code></td><td><code>boolean</code><br><code>false</code></td><td>Capture a lightweight inventory of each visited page on <em>passing</em> runs — the interactive controls (role + accessible name) and links (name, with the query and hash stripped from the href) present as the test navigates — so the dashboard can tell which controls and links the suite exposes but never exercises. Only names and hrefs are captured, never field values; a page&#39;s controls are read at most once per worker per run. <strong>Defaults to <code>false</code></strong> — opt in with <code>capturePageInventory: true</code> (or <code>PIWI_CAPTURE_PAGE_INVENTORY=true</code>). Automatically disabled when <code>collectPerformanceMetrics</code> is <code>false</code>.</td></tr><tr><td><code id="capturecodereach">captureCodeReach</code><br><code>PIWI_CAPTURE_CODE_REACH</code></td><td><code>boolean</code><br><code>false</code></td><td>Record which application source files each test executes: the files whose functions ran, from Chromium&#39;s JavaScript coverage, resolved through the dev server&#39;s module URLs or the bundle&#39;s source maps. It answers &quot;which tests reach this file?&quot; for test selection, change coverage and <code>piwi preflight</code>. Only repository-relative file paths are sent. Chromium only; other browsers record nothing. It slows the page&#39;s JavaScript, so run it on one scheduled job rather than every run. <strong>Defaults to <code>false</code></strong> — opt in with <code>captureCodeReach: true</code> (or <code>PIWI_CAPTURE_CODE_REACH=true</code>). Automatically disabled when <code>collectPerformanceMetrics</code> is <code>false</code>.</td></tr><tr><td><code id="codereachroots">codeReachRoots</code><br><code>PIWI_CODE_REACH_ROOTS</code></td><td><code>string[]</code><br><code>the Playwright config&#39;s directory</code></td><td>The directories module paths and source-map sources are resolved against for <code>captureCodeReach</code>, relative to the Playwright config, before the repository root, which is always tried last. Defaults to the Playwright config&#39;s directory. Set it to the dev server&#39;s root when that is not the config&#39;s directory (Nuxt: <code>[&#39;app&#39;]</code>).</td></tr><tr><td><code id="captureservertraces">captureServerTraces</code><br><code>PIWI_CAPTURE_SERVER_TRACES</code></td><td><code>boolean</code><br><code>true</code></td><td>Capture server-side spans for each API/document request the test makes, read from the <code>X-Piwi-Trace</code> response header emitted by a Piwi instrumentation plugin (e.g. <code>@piwitests/instrumentation-nitro</code>). The spans show up next to the network request in the dashboard and feed AI diagnosis. Free when no instrumentation is present (the header is simply absent). Defaults to <code>true</code>; automatically disabled when <code>collectPerformanceMetrics</code> is <code>false</code>. Can also be forced off with <code>PIWI_CAPTURE_SERVER_TRACES=false</code>.</td></tr><tr><td><code id="captureresources">captureResources</code><br><code>PIWI_CAPTURE_RESOURCES</code></td><td><code>boolean</code><br><code>true</code></td><td>Keep a ledger of the browsers, contexts, pages and API request contexts each test opens, and list at the end of the run the ones left open after the scope that created them ended (a context a test never closed, a <code>beforeAll</code> context no <code>afterAll</code> closes, a browser a test launched itself), the pages opened and never used, and the pages, listeners and route handlers piling up on a page or context that lives across tests. Each finding names the line or the fixture that opened the object. Rides the capture fixtures and costs a few bookkeeping steps per test. Also samples the run&#39;s processes and the machine, with or without the fixtures, and prints what the run cost: CPU by process, time spent waiting for a CPU, peak memory and disk. The findings, the run&#39;s cost and each test&#39;s go to the dashboard with the run, on its Resources tab. Defaults to <code>true</code>. Set to <code>false</code> (or <code>PIWI_CAPTURE_RESOURCES=false</code>) to turn both off.</td></tr><tr><td><code id="leakcheck">leakCheck</code><br><code>PIWI_LEAK_CHECK</code></td><td><code>&#39;report&#39; | &#39;fail&#39; | &#39;close&#39;</code><br><code>&#39;report&#39;</code></td><td>What the capture fixtures do when a test leaves open a browser, context, page or API request context that the test itself opened (its body or its <code>beforeEach</code>/<code>afterEach</code> hooks; a fixture&#39;s objects are the fixture&#39;s): <code>&#39;report&#39;</code> lists it in the end-of-run summary, <code>&#39;fail&#39;</code> also fails the test with the line that opened it, and <code>&#39;close&#39;</code> closes it when the test ends and still lists it. A <code>beforeAll</code> object left open is only ever reported. Each test is judged when it ends, so a test that hands what it opened to the next one fails under <code>&#39;fail&#39;</code> and loses it under <code>&#39;close&#39;</code>: open such objects in <code>beforeAll</code> and close them in <code>afterAll</code>. Defaults to <code>&#39;report&#39;</code>. Can also be set with <code>PIWI_LEAK_CHECK</code>.</td></tr><tr><td><code id="sampleariaonpass">sampleAriaOnPass</code><br><code>PIWI_SAMPLE_ARIA_ON_PASS</code></td><td><code>boolean</code><br><code>true</code></td><td>Sample the ARIA snapshot at the end of a <em>passing</em> test, so a later failure can be diffed against the page as it last looked when green. Rate-limited by the server: at run start the reporter asks which tests are due a fresh sample (their newest green snapshot is older than a day, or missing) and captures only those, so steady-state runs pay nothing. Rides the existing capture fixtures — no snapshot is taken without them. Defaults to <code>true</code>. Set to <code>false</code> (or <code>PIWI_SAMPLE_ARIA_ON_PASS=false</code>) to never sample on pass.</td></tr><tr><td><code id="uploadmanifest">uploadManifest</code><br><code>PIWI_UPLOAD_MANIFEST</code></td><td><code>boolean</code><br><code>true</code></td><td>Upload the application&#39;s declared surface at run start: a committed <code>piwi.manifest.json</code> next to the Playwright config, and — when the base URL&#39;s first response carries an instrumentation header — the instrumentation package&#39;s <code>/__piwi/manifest</code>. A route or page the manifest declares that no test reaches becomes a &quot;declared, never hit&quot; gap. Defaults to <code>true</code>; set to <code>false</code> (or <code>PIWI_UPLOAD_MANIFEST=false</code>) to never upload.</td></tr><tr><td><code id="defaultcapture">defaultCapture</code><br><code>PIWI_DEFAULT_CAPTURE</code></td><td><code>boolean</code><br><code>true</code></td><td>When installed via <code>wrapConfig</code>, default Playwright&#39;s own <code>screenshot</code> and <code>trace</code> options on the top-level <code>use</code> block so a failing test keeps a screenshot (<code>&#39;only-on-failure&#39;</code>) and a trace (<code>&#39;retain-on-failure&#39;</code>) even without the capture fixtures — the trace alone unlocks the DOM snapshot, full call stack, full network with bodies and the visual diff. On Playwright 1.63 or later the trace default also turns on the per-action aria tree (<code>snapshots: { dom: true, aria: true }</code>), which adds the accessibility tree before and after each action at negligible size. The <code>screen</code> snapshot kind (a PNG per action, the trace&#39;s biggest cost) stays opt-in — set it yourself with <code>use: { trace: { mode: &#39;retain-on-failure&#39;, snapshots: { dom: true, aria: true, screen: true } } }</code>. Only fills options the config leaves unset; an explicit value (including <code>&#39;off&#39;</code>) and per-project <code>use</code> blocks are never touched. Defaults to <code>true</code>. Set to <code>false</code> (or <code>PIWI_DEFAULT_CAPTURE=false</code>) to opt out and let Playwright&#39;s own defaults stand.</td></tr></tbody></table><h2 id="app-under-test" tabindex="-1">App under test <a class="header-anchor" href="#app-under-test" aria-label="Permalink to &quot;App under test&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option and variable</th><th>Type and default</th><th>Description</th></tr></thead><tbody><tr><td><code id="checkbaseurl">checkBaseUrl</code><br><code>PIWI_CHECK_BASE_URL</code></td><td><code>boolean</code><br><code>false</code></td><td>Check that each <code>baseURL</code> the run&#39;s projects use answers before any worker starts, and stop the run with a message naming the ones that do not, so a suite never runs against an environment that is down. Any HTTP answer counts (a redirect or a 404 included) except a 502, 503 or 504 from a gateway; each base URL gets three tries of 10 seconds, 2 seconds apart, sent with the project&#39;s <code>ignoreHTTPSErrors</code> and <code>proxy</code>. A stopped run runs no test and reaches no dashboard. The check runs in the reporter&#39;s global setup, after <code>webServer</code> has started and before the config&#39;s own <code>globalSetup</code>, so leave it off when that setup is what starts the app. Only the projects <code>--project</code> selects are checked. <strong>Defaults to <code>false</code></strong>. Can also be set with <code>PIWI_CHECK_BASE_URL=true</code>.</td></tr></tbody></table><h2 id="local-debugging-aids-headed-runs-only-never-under-ci" tabindex="-1">Local debugging aids (headed runs only, never under CI) <a class="header-anchor" href="#local-debugging-aids-headed-runs-only-never-under-ci" aria-label="Permalink to &quot;Local debugging aids (headed runs only, never under CI)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option and variable</th><th>Type and default</th><th>Description</th></tr></thead><tbody><tr><td><code id="inspectonfailure">inspectOnFailure</code><br><code>PIWI_INSPECT_ON_FAIL</code></td><td><code>boolean</code><br><code>false</code></td><td>Open Piwi&#39;s own failure-time overlay on the failing page — for inspecting the page and picking a locator for any element (click an element → confirm a ranked replacement locator). This is Piwi&#39;s own in-page overlay, not Playwright&#39;s native inspector, so a confirmed pick flows back into the dashboard. <code>pickLocatorOnFailure</code> opens the same overlay targeted at the broken locator; this opens it for the whole page. Local debugging aid: only takes effect in a headed browser (<code>headless: false</code> / <code>--headed</code>), never under CI, and only on a test&#39;s final attempt when retries are configured. The run waits until the overlay is resolved. Defaults to <code>false</code>. Can also be enabled with <code>PIWI_INSPECT_ON_FAIL=true</code>.</td></tr><tr><td><code id="picklocatoronfailure">pickLocatorOnFailure</code><br><code>PIWI_PICK_LOCATOR_ON_FAIL</code></td><td><code>boolean</code><br><code>false</code></td><td>Open Piwi&#39;s locator picker on the failing page when a locator action fails: click the element the locator should have matched, confirm one of the ranked replacement locators generated for it, and the choice is recorded — folded into the run&#39;s locator snapshots (so the dashboard&#39;s healing panel shows it) and attached as <code>piwi-user-pick</code> with a report annotation. Same gate as <code>inspectOnFailure</code>: headed browser only, never under CI, final attempt only. Defaults to <code>false</code>. Can also be enabled with <code>PIWI_PICK_LOCATOR_ON_FAIL=true</code>.</td></tr></tbody></table><h2 id="streaming" tabindex="-1">Streaming <a class="header-anchor" href="#streaming" aria-label="Permalink to &quot;Streaming&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option and variable</th><th>Type and default</th><th>Description</th></tr></thead><tbody><tr><td><code id="streaming">streaming</code><br><code>PIWI_STREAMING</code></td><td><code>boolean</code><br><code>true</code></td><td>Enable live streaming of results (falls back to batch if unsupported). Defaults to <code>true</code>.</td></tr><tr><td><code id="streamingbatchsize">streamingBatchSize</code><br><code>PIWI_STREAMING_BATCH_SIZE</code></td><td><code>number</code><br><code>20</code></td><td>Number of queued events that triggers a send during streaming: test starts and results, and live steps while someone has the run open on the dashboard. Defaults to <code>20</code>.</td></tr><tr><td><code id="streamingbatchdelay">streamingBatchDelay</code><br><code>PIWI_STREAMING_BATCH_DELAY</code></td><td><code>number</code><br><code>2000</code></td><td>Max delay (ms) before flushing pending events during streaming. Defaults to <code>2000</code>.</td></tr><tr><td><code id="maxstreambufferbytes">maxStreamBufferBytes</code><br><code>PIWI_MAX_STREAM_BUFFER_BYTES</code></td><td><code>number</code><br><code>104857600</code> (100 MB)</td><td>Byte budget for the in-memory stream buffer (the queue of events waiting to reach the dashboard, and the crash-recovery file it writes if delivery fails). When the server is unreachable or a huge suite outruns delivery, the queue is capped here instead of growing without bound: the lowest-value events are shed first — live step progress, then per-test <code>begin</code> markers, and only as a last resort test results (the final counts and the end-of-run batch submit stay complete regardless). Defaults to <code>104857600</code> (100 MB). Set to <code>0</code> to disable the cap (unbounded, the pre-<code>0.28</code> behavior). Can also be set with <code>PIWI_MAX_STREAM_BUFFER_BYTES</code>.</td></tr></tbody></table><h2 id="ci-gate" tabindex="-1">CI gate <a class="header-anchor" href="#ci-gate" aria-label="Permalink to &quot;CI gate&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option and variable</th><th>Type and default</th><th>Description</th></tr></thead><tbody><tr><td><code id="failonflakytests">failOnFlakyTests</code><br><code>PIWI_FAIL_ON_FLAKY_TESTS</code></td><td><code>boolean</code><br><code>false</code></td><td>Fail the run when any test was flaky (passed only after a retry). Forwarded to Playwright&#39;s native <code>failOnFlakyTests</code> config option (Playwright 1.52+) when the reporter is installed via <code>wrapConfig</code>, so a flaky-only run exits non-zero without any server round-trip. Defaults to <code>false</code>. Can also be set with <code>PIWI_FAIL_ON_FLAKY_TESTS</code>.</td></tr></tbody></table><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option and variable</th><th>Type and default</th><th>Description</th></tr></thead><tbody><tr><td><code id="username">username</code><br><code>PIWI_USERNAME</code></td><td><code>string | null</code><br><code>null</code></td><td>Username for dashboard login (use <code>apiKey</code> instead when possible)</td></tr><tr><td><code id="password">password</code><br><code>PIWI_PASSWORD</code></td><td><code>string | null</code><br><code>null</code></td><td>Password for dashboard login (used with <code>username</code>)</td></tr><tr><td><code id="apikey">apiKey</code><br><code>PIWI_API_KEY</code></td><td><code>string | null</code><br><code>null</code></td><td>API key for authentication (preferred over <code>username</code>/<code>password</code> for CI)</td></tr></tbody></table><h2 id="run-metadata" tabindex="-1">Run metadata <a class="header-anchor" href="#run-metadata" aria-label="Permalink to &quot;Run metadata&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option and variable</th><th>Type and default</th><th>Description</th></tr></thead><tbody><tr><td><code id="reports">reports</code></td><td><code>Array&lt;{ type: string; dir?: string; label?: string }&gt;</code><br>no default</td><td>Additional report types to upload. Each entry can specify <code>type</code>, optional <code>dir</code>, and optional <code>label</code>.</td></tr><tr><td><code id="runlabel">runLabel</code><br><code>PIWI_RUN_LABEL</code></td><td><code>string</code><br>no default</td><td>Stable label that ties shards together (e.g. CI run ID). Auto-detected from CI env, with the CI job&#39;s id added for a run that is not sharded; a label set here is used as it is. Override it when your CI is not detected, or to keep matrix legs that report to one project apart.</td></tr><tr><td><code id="environment">environment</code><br><code>PIWI_ENVIRONMENT</code></td><td><code>string</code><br>no default</td><td>Deployment environment for this run, e.g. <code>&quot;production&quot;</code>, <code>&quot;staging&quot;</code>, <code>&quot;integration&quot;</code></td></tr><tr><td><code id="label">label</code><br><code>PIWI_LABEL</code></td><td><code>string</code><br>no default</td><td>Optional display label for the test run (e.g. &quot;v2.3.1 release&quot;)</td></tr><tr><td><code id="keep">keep</code><br><code>PIWI_KEEP</code></td><td><code>boolean</code><br><code>false</code></td><td>Keep this run forever: the dashboard&#39;s retention never deletes it. Set it for the runs worth keeping, such as release or tag builds. Defaults to <code>false</code>. Can also be set with <code>PIWI_KEEP=true</code>.</td></tr><tr><td><code id="relatedissue">relatedIssue</code></td><td><code>string</code><br>no default</td><td>Related issue reference, e.g. <code>&quot;JIRA-123&quot;</code></td></tr><tr><td><code id="ciinfo">ciInfo</code></td><td><code>string</code><br>no default</td><td>CI job information</td></tr><tr><td><code id="tags">tags</code></td><td><code>string[]</code><br>no default</td><td>Tags to categorize the test run</td></tr><tr><td><code id="customdata">customData</code></td><td><code>Record&lt;string, unknown&gt;</code><br>no default</td><td>Additional custom metadata as key-value pairs</td></tr></tbody></table><h2 id="ai-steps" tabindex="-1">AI steps <a class="header-anchor" href="#ai-steps" aria-label="Permalink to &quot;AI steps&quot;">​</a></h2><p><strong><code>ai</code></strong> (object). Natural-language locators and flows (<code>page.piwiLocator(...)</code> / <code>page.piwiRun(...)</code>). An agent resolves each prompt once into a committed, deterministic artifact; every run replays that artifact with plain Playwright calls — zero LLM calls in the default <code>replay</code> mode.</p><table tabindex="0"><thead><tr><th>Option and variable</th><th>Type and default</th><th>Description</th></tr></thead><tbody><tr><td><code id="ai-mode">ai.mode</code><br><code>PIWI_AI</code></td><td><code>&#39;replay&#39; | &#39;resolve&#39; | &#39;heal&#39;</code><br><code>replay</code></td><td><code>replay</code> (default) executes committed artifacts read-only and fails closed on a miss; <code>resolve</code> authors missing entries; <code>heal</code> repairs entries that no longer replay. Can also be set with <code>PIWI_AI</code>.</td></tr><tr><td><code id="ai-dir">ai.dir</code><br><code>PIWI_AI_DIR</code></td><td><code>string</code><br><code>__piwi__</code></td><td>Directory name (per spec) that holds the committed entries. Defaults to <code>__piwi__</code>. Can also be set with <code>PIWI_AI_DIR</code>.</td></tr><tr><td><code id="ai-onmiss">ai.onMiss</code><br><code>PIWI_AI_ON_MISS</code></td><td><code>&#39;fail&#39; | &#39;fixme&#39;</code><br><code>fail</code></td><td>On a replay miss: <code>fail</code> (default) errors with repro instructions, or <code>fixme</code> marks the test fixme (yellow) instead. Can also be set with <code>PIWI_AI_ON_MISS</code>.</td></tr><tr><td><code id="ai-maxsteps">ai.maxSteps</code><br><code>PIWI_AI_MAX_FLOW_STEPS</code></td><td><code>number</code><br><code>20</code></td><td>Max steps the agent may take resolving one <code>piwiRun</code> flow (the authoring budget). Defaults to <code>20</code>. Can also be set with <code>PIWI_AI_MAX_FLOW_STEPS</code>.</td></tr><tr><td><code id="ai-maxsnapshotchars">ai.maxSnapshotChars</code><br><code>PIWI_AI_MAX_SNAPSHOT_CHARS</code></td><td><code>number</code><br><code>24000</code></td><td>Max characters of the page ARIA snapshot sent to the authoring model per iteration (cost control). Defaults to <code>24000</code>. Can also be set with <code>PIWI_AI_MAX_SNAPSHOT_CHARS</code>.</td></tr><tr><td><code id="ai-optionalprobetimeout">ai.optionalProbeTimeout</code><br><code>PIWI_AI_OPTIONAL_PROBE_TIMEOUT</code></td><td><code>number</code><br><code>2000</code></td><td>Timeout (ms) for the existence probe of an <code>optional</code> step during replay. Defaults to <code>2000</code>. Can also be set with <code>PIWI_AI_OPTIONAL_PROBE_TIMEOUT</code>.</td></tr><tr><td><code id="ai-responsewaittimeout">ai.responseWaitTimeout</code><br><code>PIWI_AI_RESPONSE_WAIT_TIMEOUT</code></td><td><code>number</code><br>no default</td><td>Timeout (ms) for a step&#39;s <code>waitForResponse</code> (the Ajax wait) during replay, and the network-settle window during authoring. Omitted uses Playwright&#39;s default action timeout. Can also be set with <code>PIWI_AI_RESPONSE_WAIT_TIMEOUT</code>.</td></tr><tr><td><code id="ai-screenshotfallback">ai.screenshotFallback</code><br><code>PIWI_AI_SCREENSHOT_FALLBACK</code></td><td><code>boolean</code><br>no default</td><td>Send a screenshot to the authoring model as a vision fallback when the page&#39;s ARIA snapshot is empty (a canvas-heavy page the model otherwise can&#39;t ground against). <strong>Requires a vision-capable model</strong> — leave it off (the default) for models that don&#39;t accept images. Only affects <code>resolve</code>/<code>heal</code>, never replay. Can also be set with <code>PIWI_AI_SCREENSHOT_FALLBACK</code>.</td></tr></tbody></table><h2 id="output-diagnostics" tabindex="-1">Output &amp; diagnostics <a class="header-anchor" href="#output-diagnostics" aria-label="Permalink to &quot;Output &amp; diagnostics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option and variable</th><th>Type and default</th><th>Description</th></tr></thead><tbody><tr><td><code id="outputfile">outputFile</code><br><code>PIWI_OUTPUT_FILE</code></td><td><code>string</code><br>no default</td><td>Write a JSON file with the submitted run&#39;s dashboard URL, id, project id and status after the run lands, so a CI pipeline can consume it (e.g. feed the run URL into a custom email step). Any CI can read the file. GitHub Actions step outputs / job summary and GitLab dotenv reports are emitted automatically when running under those systems, regardless of this option. Can also be set with <code>PIWI_OUTPUT_FILE</code>.</td></tr><tr><td><code id="verbose">verbose</code><br><code>PIWI_VERBOSE</code></td><td><code>boolean</code><br><code>false</code></td><td>Enable verbose logging for debugging. Defaults to <code>false</code>.</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/reporter.html">Reporter</a>: installing the reporter and wiring it into <code>playwright.config.ts</code>.</li><li><a href="/reference/test-metadata.html">Test metadata</a>: annotations and tags the reporter reads from your tests.</li><li><a href="/reference/configuration.html">Configuration reference</a>: the <code>PIWI_*</code> environment variables the dashboard server reads.</li></ul>',28)])])}const f=t(r,[["render",c]]);export{p as __pageData,f as default};
